<x-layouts::app title="Kelola Pengguna"><div class="row g-4"><div class="col-xl-7"><section class="workspace-card"><div class="panel-heading"><h2>Pengguna pengelola</h2><p>Akses hanya diberikan melalui akun yang disiapkan administrator.</p></div><div class="table-responsive"><table class="table portal-table"><thead><tr><th>Pengguna</th><th>Peran</th><th>Status</th><th>Aksi</th></tr></thead><tbody>@foreach($users as $user)<tr><td><strong>{{ $user->name }}</strong><small class="d-block text-muted">{{ $user->login_id }}<br>{{ $user->email }}</small></td><td>{{ $user->role->label() }}</td><td><span class="badge text-bg-{{ $user->account_state === App\Enums\AccountState::Active ? 'success' : 'secondary' }}">{{ $user->account_state->label() }}</span></td><td>@if($user->id === auth()->id())<span class="small text-muted">Akun Anda</span>@else<form method="post" action="{{ route('admin.users.toggle', $user) }}">@csrf @method('patch')<input type="hidden" name="expected_state" value="{{ $user->account_state->value }}"><label class="visually-hidden" for="reason-{{ $user->id }}">Alasan perubahan akses {{ $user->name }}</label><input id="reason-{{ $user->id }}" name="reason" class="form-control form-control-sm mb-2" placeholder="Alasan perubahan akses" required minlength="10" maxlength="1000"><button class="btn btn-sm btn-outline-purple">{{ $user->account_state === App\Enums\AccountState::Disabled ? 'Aktifkan' : 'Nonaktifkan' }}</button></form>@endif</td></tr>@endforeach</tbody></table></div><div class="panel-body">{{ $users->links() }}</div></section></div><div class="col-xl-5"><section class="workspace-card"><div class="panel-heading"><h2>Tambah pengelola</h2></div><div class="panel-body"><form method="post" action="{{ route('admin.users.store') }}">@csrf @foreach(['name'=>'Nama','login_id'=>'ID login','email'=>'Email (opsional)'] as $key=>$label)<div class="mb-3"><label for="staff-{{ $key }}" class="form-label">{{ $label }}</label><input id="staff-{{ $key }}" name="{{ $key }}"